from bisect import bisect_right


def two_sum(xs, target):
    """
    Return the pair of indices (i, j) with i < j such that
    xs[i] + xs[j] == target, choosing the pair with the smallest i,
    then the smallest j. Return None if no such pair exists.
    """
    if not xs:
        return None

    # Map each value to the sorted list of indices where it occurs.
    positions = {}
    for idx, value in enumerate(xs):
        positions.setdefault(value, []).append(idx)

    for i, value in enumerate(xs):
        complement = target - value
        if complement in positions:
            idx_list = positions[complement]
            # Find the smallest index j strictly greater than i.
            pos = bisect_right(idx_list, i)
            if pos < len(idx_list):
                return (i, idx_list[pos])

    return None
